// ComponentPreviewFrame — the SNAPSHOT channel (epic-job-applications). The iframe is opaque-origin, so the host
// asks it for markup by message and the frame turns the reply into a promise. Only a reply from THIS frame's
// window may resolve it — a concurrent preview answering the same id must not feed the wrong page to the printer.
import { describe, it, expect, vi, afterEach } from "vitest";
import { render, waitFor, cleanup, act } from "@testing-library/react";
import "@/features/designs";
import { useAppStore } from "@/store";
import { ComponentPreviewFrame } from "@/features/designs/ComponentPreviewFrame";
import type { ComponentRecord } from "@/features/designs/lib/model";

vi.mock("@/features/designs/lib/componentBridge", async (importOriginal) => ({
  ...(await importOriginal<typeof import("@/features/designs/lib/componentBridge")>()),
  recordPreviewError: vi.fn(async () => {}),
  clearPreviewError: vi.fn(async () => {}),
}));

const comp: ComponentRecord = {
  id: "resumeclassic", name: "ResumeClassic", kitId: "test-kit", role: "document", version: "", used: 0,
  tags: [], variants: ["default"], composes: [], props: [], whenUse: [], whenNot: [], src: "x.tsx", srcText: `<ResumeClassic />`,
};

describe("ComponentPreviewFrame — snapshot", () => {
  afterEach(() => cleanup());

  it("asks the iframe for markup and resolves with ITS reply only", async () => {
    useAppStore.setState({ kits: [{ id: "test-kit", name: "Test" }], components: [] } as never);
    let snap: ((sel: string) => Promise<string | null>) | null = null;
    const { container } = render(
      <ComponentPreviewFrame comp={comp} theme="light" themeId="d" themeVars={{}} width={200} registerSnapshot={(s) => { snap = s; }} />,
    );
    await waitFor(() => expect(snap).not.toBeNull());
    const iframe = container.querySelector("iframe")!;
    const posted = vi.spyOn(iframe.contentWindow!, "postMessage");
    const pending = snap!("[data-document]");
    expect(posted).toHaveBeenCalledWith({ __snapshot: { id: 1, selector: "[data-document]" } }, "*");
    await act(async () => {
      // A reply from some OTHER window, carrying the same id, is ignored…
      window.dispatchEvent(new MessageEvent("message", { data: { __snapshotReply: { id: 1, html: "<p>wrong page</p>" } }, source: window }));
      // …and this frame's own reply resolves it.
      window.dispatchEvent(new MessageEvent("message", { data: { __snapshotReply: { id: 1, html: "<article data-document>ok</article>" } }, source: iframe.contentWindow }));
    });
    await expect(pending).resolves.toBe("<article data-document>ok</article>");
  });

  it("withdraws the snapshot when it unmounts", async () => {
    useAppStore.setState({ kits: [{ id: "test-kit", name: "Test" }], components: [] } as never);
    const register = vi.fn();
    const { unmount } = render(<ComponentPreviewFrame comp={comp} theme="light" themeId="d" themeVars={{}} width={200} registerSnapshot={register} />);
    await waitFor(() => expect(register).toHaveBeenCalledWith(expect.any(Function)));
    unmount();
    expect(register).toHaveBeenLastCalledWith(null);
  });
});
